// Generates the shop pages from assets/catalogue.json: collection.html and collection/<product>.html.
// Run by scripts/build.js (header and footer are injected afterwards). Do not edit the generated pages by hand:
// change the copy or prices in assets/catalogue.json, or the layout in this file, then run: node scripts/build.js
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const cat = JSON.parse(fs.readFileSync(path.join(root, 'assets/catalogue.json'), 'utf8'));
const SITE = 'https://onyxaura.in';

const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const inr = n => '₹' + n.toLocaleString('en-IN');
const range = (r, unit) => r[0].toFixed(unit ? 0 : 1) + ' to ' + r[1].toFixed(unit ? 0 : 1) + (unit ? ' ' + unit : '');
const FMT = { can: 'Can', glass: 'Glass' };
const coming = p => p.status === 'coming';
const packPrice = (v, pk) => (typeof pk.price === 'number' ? pk.price : v.price * pk.units);
const defVar = p => p.variants.find(v => v.format === p.defaultFormat) || p.variants[0];
const alt = (p, v, view) => 'OnyxAura ' + p.name + ', ' + v.label.toLowerCase() + ' ' + v.volume + (view ? ': ' + view.toLowerCase() : '');
const fromPrice = p => Math.min(...p.variants.filter(v => typeof v.price === 'number').map(v => v.price));

/* a line drawing of a can, for a piece that has no photograph yet */
const canArt = `<svg class="soon-art" viewBox="0 0 400 500" aria-hidden="true" focusable="false"><g fill="none" stroke-linecap="round" stroke-linejoin="round"><path class="ln" pathLength="1" d="M140 96h120l12 22v276l-12 22H140l-12-22V118z"/><path class="ln" pathLength="1" d="M128 118h144M128 394h144"/><path class="ln" pathLength="1" d="M156 96v-8h88v8"/><path class="gd" pathLength="1" d="M200 170c-28 0-44 22-44 48 0 30 20 52 44 52s44-22 44-52c0-26-16-48-44-48z"/><path class="gd" pathLength="1" d="M178 200c8-10 36-10 44 0"/><path class="ln" pathLength="1" d="M170 320h60M182 340h36"/></g></svg>`;

function head(o) {
  const og = o.og;
  return `<!DOCTYPE html>
<!-- GENERATED by scripts/build-shop.js from assets/catalogue.json. Edit those, not this file. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1">
<title>${esc(o.title)}</title>
<meta name="description" content="${esc(o.desc)}">
<link rel="canonical" href="${SITE}${o.path}">
<meta property="og:type" content="${o.ogType || 'website'}">
<meta property="og:site_name" content="ONYXAURA">
<meta property="og:title" content="${esc(o.title)}">
<meta property="og:description" content="${esc(o.desc)}">
<meta property="og:url" content="${SITE}${o.path}">
<meta property="og:image" content="${SITE}${og.src}">
<meta property="og:image:width" content="${og.w}">
<meta property="og:image:height" content="${og.h}">
<meta property="og:image:alt" content="${esc(og.alt)}">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="${esc(o.title)}">
<meta name="twitter:description" content="${esc(o.desc)}">
<meta name="twitter:image" content="${SITE}${og.src}">
<script type="application/ld+json">${JSON.stringify(o.ld)}</script>
<meta name="theme-color" content="#070707">
<script>document.documentElement.className+=" js"</script>
<link rel="icon" href="/assets/logo-mark.svg" type="image/svg+xml">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Bodoni+Moda:ital,opsz,wght@0,6..96,400;0,6..96,500;1,6..96,400&family=Hanken+Grotesk:wght@300;400;500;600&display=swap" rel="stylesheet">
<link rel="stylesheet" href="/assets/site.css">
<link rel="stylesheet" href="/assets/shop.css">
</head>
`;
}

const goldStrip = `<a class="gold-strip" href="/gold"><span class="caps gold">Gold</span><span class="serif">Allocated, not sold.</span><span class="caps go">Enter Gold</span></a>`;
const crumbLd = (items) => ({ '@type': 'BreadcrumbList', itemListElement: items.map((x, i) => ({ '@type': 'ListItem', position: i + 1, name: x[0], item: SITE + x[1] })) });

/* ---------- collection ---------- */
function card(p) {
  if (coming(p)) {
    const sd = defVar(p), pics = sd.card ? `<img class="a" src="${sd.card[0]}" alt="${esc(alt(p, sd))}" width="1000" height="1250" loading="lazy">` + (sd.card[1] ? `\n    <img class="b" src="${sd.card[1]}" alt="" width="600" height="750" loading="lazy">` : '') : canArt;
    return `<article class="pcard soon${sd.card ? ' has-img' : ''}" id="${p.id}" data-product="${p.id}" data-formats="${p.variants.map(v => v.format).join(' ')}">
  <a class="pimg" href="/collection/${p.id}" aria-label="${esc(p.name)}: coming soon">
    ${pics}
    <span class="num serif">${p.numeral}</span><span class="soon-tag caps">Coming soon</span>
  </a>
  <div class="pbody">
    <h2><a href="/collection/${p.id}">${esc(p.name)}</a></h2>
    <p class="tag">${esc(p.tagline)}</p>
    <p class="small spec-line">${esc(p.variants.map(v => FMT[v.format] + ' ' + v.volume).join(' · ') + ' · pH ' + range(p.ph))}</p>
    <div class="prow"><span class="price soon-p">In preparation</span><a class="btn ghost" href="/contact?seg=other&amp;about=${p.id}">Register interest</a></div>
    <a class="more caps" href="/collection/${p.id}">Details</a>
  </div>
</article>`;
  }
  const d = defVar(p), imgs = {};
  p.variants.forEach(v => { imgs[v.format] = v.card; });
  const spec = p.variants.map(v => FMT[v.format] + ' ' + v.volume).join(' · ') + ' · pH ' + range(p.ph);
  const fmtBtns = p.variants.length > 1 ? `<div class="seg mini" role="group" aria-label="${esc(p.name)} format">${p.variants.map(v => `<button type="button" class="${v === d ? 'on' : ''}" data-sku="${v.sku}" data-format="${v.format}" data-price="${v.price}" data-alt="${esc(alt(p, v))}" aria-pressed="${v === d}">${FMT[v.format]} ${esc(v.volume)}</button>`).join('')}</div>`
    : `<div class="seg mini solo" role="group" aria-label="${esc(p.name)} format"><button type="button" class="on" data-sku="${d.sku}" data-format="${d.format}" data-price="${d.price}" data-alt="${esc(alt(p, d))}" aria-pressed="true">${esc(d.label)} ${esc(d.volume)}</button></div>`;
  return `<article class="pcard" id="${p.id}" data-product="${p.id}" data-formats="${p.variants.map(v => v.format).join(' ')}" data-imgs='${JSON.stringify(imgs)}'>
  <a class="pimg" href="/collection/${p.id}" aria-label="${esc(p.name)}: view details">
    <img class="a" src="${d.card[0]}" alt="${esc(alt(p, d))}" width="1000" height="1250" loading="lazy">
    <img class="b" src="${d.card[1]}" alt="" width="1000" height="1250" loading="lazy">
    <span class="num serif">${p.numeral}</span>
  </a>
  <div class="pbody">
    <h2><a href="/collection/${p.id}">${esc(p.name)}</a></h2>
    <p class="tag">${esc(p.tagline)}</p>
    <p class="small spec-line">${esc(spec)}</p>
    ${fmtBtns}
    <div class="prow"><span class="price-wrap"><span class="mrp caps">MRP</span><span class="price" data-amount>${inr(d.price)}</span></span><button type="button" class="btn primary" data-add>Add to cart</button></div>
    <a class="more caps" href="/collection/${p.id}">Details</a>
  </div>
</article>`;
}

function collectionPage() {
  const title = 'Collection: One Standard, Four Waters — ONYXAURA';
  const desc = 'Incline, Black Water and Himalayan: Himalayan waters filtered, balanced and sealed in Bengaluru. Glass bottles from ₹399 and clear cans from ₹125 MRP. Order online.';
  const ld = { '@context': 'https://schema.org', '@graph': [
    { '@type': 'CollectionPage', '@id': SITE + '/collection#webpage', url: SITE + '/collection', name: 'Collection', description: desc, inLanguage: 'en',
      isPartOf: { '@type': 'WebSite', name: 'ONYXAURA', url: SITE + '/' }, breadcrumb: { '@id': SITE + '/collection#breadcrumb' },
      mainEntity: { '@type': 'ItemList', itemListElement: cat.products.map((p, i) => ({ '@type': 'ListItem', position: i + 1, url: SITE + '/collection/' + p.id, name: p.name })) } },
    Object.assign({ '@id': SITE + '/collection#breadcrumb' }, crumbLd([['Home', '/'], ['Collection', '/collection']]))
  ] };
  const live = cat.products.filter(p => !coming(p));
  return head({ title, desc, path: '/collection', ld, og: { src: '/assets/products/collection-og.jpg', w: 1200, h: 630, alt: 'OnyxAura Incline in glass, Black Water in a clear can and Himalayan in a clear can, side by side on black.' } }) + `<body data-page="collection" class="shop-page">
<!--HEADER--><!--/HEADER-->
<main>
<section class="page-hero shop-hero">
  <div class="wrap">
    <p class="caps gold" style="margin-bottom:26px">Collection</p>
    <h1>One standard. Four waters.</h1>
    <p class="lead">Drawn high in the Himalaya, filtered and balanced in our own plant near Bengaluru, sealed and coded batch by batch. What changes is the occasion.</p>
    <ul class="shop-facts" aria-label="At a glance">
      <li><b>${live.length}</b><span>waters on sale today</span></li>
      <li><b>${inr(Math.min(...live.map(fromPrice)))}</b><span>MRP, from</span></li>
      <li><b>7</b><span>stations on the line</span></li>
      <li><b>1&ndash;2 wk</b><span>delivery across India</span></li>
    </ul>
  </div>
</section>
<section class="shop-sec">
  <div class="wrap">
    <div class="shop-bar">
      <div class="seg" role="group" aria-label="Filter by format"><button type="button" class="on" data-f="all" aria-pressed="true">All</button><button type="button" data-f="glass" aria-pressed="false">Glass</button><button type="button" data-f="can" aria-pressed="false">Can</button></div>
      <p class="small" data-count aria-live="polite">${cat.products.length} pieces</p>
    </div>
    <div class="pgrid"><!--PRODUCTS-->
${cat.products.map(card).join('\n')}
<!--/PRODUCTS--></div>
    <p class="empty small" data-empty hidden>Nothing in that format.</p>
    ${goldStrip}
    <p class="note" style="margin-top:44px">All prices are MRP, inclusive of all taxes. pH and TDS are target specifications; every batch is tested and recorded before it leaves the plant, and the report is available on request.</p>
    <p class="small" style="margin-top:22px">Ordering for a venue, a cabin or an event? <a class="link" href="/contact?seg=corporate">Write to us.</a></p>
  </div>
</section>
</main>
<!--FOOTER--><!--/FOOTER-->
<script src="/assets/site.js"></script>
<script src="/assets/shop.js" defer></script>
</body>
</html>
`;
}

/* ---------- product ---------- */
function productPage(p) {
  const d = defVar(p), path_ = '/collection/' + p.id, soon = coming(p);
  const title = p.name + ': ' + p.tagline.replace(/\.$/, '').replace(/\. Coming soon$/, '') + ' — ONYXAURA';
  const others = cat.products.filter(x => x.id !== p.id);
  const images = [...new Set(p.variants.flatMap(v => (v.images || []).map(i => SITE + i.src)))];
  const ldProduct = {
    '@type': 'Product', '@id': SITE + path_ + '#product', name: 'OnyxAura ' + p.name, description: p.lead, category: p.kind,
    brand: { '@type': 'Brand', name: 'ONYXAURA' }, url: SITE + path_,
    additionalProperty: [{ '@type': 'PropertyValue', name: 'Target pH', value: range(p.ph) }]
  };
  if (images.length) ldProduct.image = images;
  if (p.tds) ldProduct.additionalProperty.push({ '@type': 'PropertyValue', name: 'Target TDS', value: range(p.tds, 'ppm') });
  if (cat.pricesConfirmed && !soon) ldProduct.offers = p.variants.flatMap(v => v.packs.map(k => ({ '@type': 'Offer', sku: v.sku + '.' + k.units, name: v.label + ' ' + v.volume + ', ' + k.label.toLowerCase(), price: String(packPrice(v, k)), priceCurrency: cat.currency, availability: 'https://schema.org/InStock', url: SITE + path_ })));
  const ld = { '@context': 'https://schema.org', '@graph': [
    { '@type': 'WebPage', '@id': SITE + path_ + '#webpage', url: SITE + path_, name: title, description: p.metaDescription, inLanguage: 'en', isPartOf: { '@type': 'WebSite', name: 'ONYXAURA', url: SITE + '/' }, breadcrumb: { '@id': SITE + path_ + '#breadcrumb' }, mainEntity: { '@id': SITE + path_ + '#product' } },
    Object.assign({ '@id': SITE + path_ + '#breadcrumb' }, crumbLd([['Home', '/'], ['Collection', '/collection'], [p.name, path_]])),
    ldProduct
  ] };
  const data = {
    id: p.id, name: p.name, defaultFormat: d.format, soon,
    views: Object.fromEntries(p.variants.map(v => [v.format, v.images || []])),
    packViews: Object.fromEntries(p.variants.flatMap(v => v.packs.filter(k => k.images).map(k => [v.sku + '.' + k.units, k.images]))),
    ranges: cat.products.map(x => ({ id: x.id, name: x.name, numeral: x.numeral, range: x.ph })),
    tds: cat.products.filter(x => x.tds).map(x => ({ id: x.id, name: x.name, range: x.tds }))
  };
  const src = p.source || {};
  const facts = [
    ['Target pH', range(p.ph)], p.tds ? ['Target TDS', range(p.tds, 'ppm')] : null,
    ['Source', src.region + (src.altitude ? ', ' + src.altitude.toLowerCase() : '')],
    ['Bottled', 'Our plant near Kempegowda International Airport, Bengaluru'],
    ['Batch', 'A batch and lot code on every pack'], ...(p.specs || [])
  ].filter(Boolean).map(f => `<div><dt>${esc(f[0])}</dt><dd>${esc(f[1])}</dd></div>`).join('');
  const origin = `<section class="origin-sec" data-origin>
  <canvas class="origin-cv" aria-hidden="true"></canvas>
  <div class="wrap origin-grid">
    <div>
      <p class="caps gold" style="margin-bottom:22px">Where it begins</p>
      <h2 class="rv">${esc(src.place || src.region)}.</h2>
      <p class="lead rv" style="margin-top:22px">${esc(p.story)}</p>
      <p class="small origin-day">${esc(src.day || '')}</p>
    </div>
    <dl class="origin-read" aria-label="The source at a glance">
      <div><dt>Region</dt><dd class="serif">${esc(src.region)}</dd></div>
      <div><dt>Altitude</dt><dd class="serif" data-alt>${esc(src.altitude)}</dd></div>
      <div><dt>Terrain</dt><dd>${esc(src.terrain)}</dd></div>
      <div><dt>Climate</dt><dd>${esc(src.climate)}</dd></div>
    </dl>
  </div>
</section>`;
  const more = others.map(o => {
    const od = defVar(o), pic = od.card ? `<span class="mimg"><img src="${od.card[0]}" alt="${esc(alt(o, od))}" width="1000" height="1250" loading="lazy"></span>` : `<span class="mimg soon">${canArt}</span>`;
    return `<a class="mini-card" href="/collection/${o.id}">${pic}<span class="serif num">${o.numeral}</span><b class="serif">${esc(o.name)}</b><span class="tag">${esc(o.tagline)}</span><span class="caps go">${coming(o) ? 'Coming soon' : 'From ' + inr(fromPrice(o)) + ' MRP'}</span></a>`;
  }).join('');
  const pageHead = head({ title, desc: p.metaDescription, path: path_, ld, ogType: 'product', og: p.og ? { src: p.og, w: 1200, h: 630, alt: 'OnyxAura ' + p.name + ' on black.' } : { src: '/assets/products/collection-og.jpg', w: 1200, h: 630, alt: 'The OnyxAura collection.' } });

  let gallery, panel;
  if (soon) {
    // photographs if there are any (the thumbnails only change the picture: there is nothing to choose yet), else a drawing
    gallery = d.images ? `<div class="gallery soon-gallery" data-soon-gallery>
      <div class="vstage"><img data-main src="${d.images[0].src}" alt="${esc(alt(p, d, d.images[0].label))}" width="1000" height="1250" fetchpriority="high"><span class="soon-tag caps">Coming soon</span></div>
      <ul class="thumbs">${d.images.map((x, i) => `<li><button type="button" class="${i === 0 ? 'on' : ''}" data-view="${i}" aria-label="${esc(x.label)}" aria-pressed="${i === 0}"><img src="${x.src}" alt="" width="600" height="750" loading="lazy"></button></li>`).join('')}</ul>
    </div>` : `<div class="gallery soon-gallery"><div class="vstage soon">${canArt}<span class="soon-tag caps">Coming soon</span></div></div>`;
    panel = `<div class="panel">
      <p class="caps gold">${p.numeral} &middot; ${esc(p.kind)}</p>
      <h1>${esc(p.name)}</h1>
      <p class="tagline serif">${esc(p.tagline)}</p>
      <p class="lead">${esc(p.lead)}</p>
      <div class="buyrow"><a class="btn primary" href="/contact?seg=other&amp;about=${p.id}">Register interest</a><a class="btn ghost" href="/collection">View the collection</a></div>
      <p class="small assure">We will write to you the day it is ready. Nothing is charged until then.</p>
      <ul class="points">${p.points.map(x => '<li>' + esc(x) + '</li>').join('')}</ul>
      <div class="acc"><details open><summary>Specification</summary><div class="acc-in"><dl class="facts">${facts}</dl></div></details></div>
    </div>`;
  } else {
    const fmtBtns = p.variants.map(v => `<button type="button" class="${v === d ? 'on' : ''}" data-format="${v.format}" data-sku="${v.sku}" aria-pressed="${v === d}">${esc(v.label)} <span class="vol">${esc(v.volume)}</span></button>`).join('');
    const packBtns = d.packs.map((pk, i) => `<button type="button" class="${i === 0 ? 'on' : ''}" data-units="${pk.units}" aria-pressed="${i === 0}">${esc(pk.label)}</button>`).join('');
    const thumbs = d.images.map((x, i) => `<li><button type="button" class="${i === 0 ? 'on' : ''}" data-view="${i}" aria-label="${esc(x.label)}" aria-pressed="${i === 0}"><img src="${x.src}" alt="" width="600" height="750" loading="lazy"></button></li>`).join('');
    const rows = p.variants.flatMap(v => v.packs.map(k => `<tr><td>${esc(v.label)}</td><td>${esc(v.volume)}</td><td>${esc(k.label)}</td><td>${inr(packPrice(v, k))}</td></tr>`)).join('');
    gallery = `<div class="gallery" data-gallery>
      <div class="vstage" data-stage tabindex="0" aria-label="${esc(p.name)} images. Use the arrow keys to change view.">
        <img data-main src="${d.images[0].src}" alt="${esc(alt(p, d, d.images[0].label))}" width="1000" height="1250" fetchpriority="high">
        <span class="hint small" data-hint>Move over the image to look closer</span>
      </div>
      <ul class="thumbs" data-thumbs>${thumbs}</ul>
    </div>`;
    panel = `<div class="panel">
      <p class="caps gold">${p.numeral} &middot; ${esc(p.kind)}</p>
      <h1>${esc(p.name)}</h1>
      <p class="tagline serif">${esc(p.tagline)}</p>
      <p class="lead">${esc(p.lead)}</p>
      ${p.variants.length > 1 ? `<div class="opt"><span class="caps">Format</span><div class="seg" role="group" aria-label="Format" data-fmt>${fmtBtns}</div></div>` : `<div class="opt" hidden><div class="seg" data-fmt>${fmtBtns}</div></div><p class="small fmt-one">${esc(d.label)} &middot; ${esc(d.volume)}</p>`}
      <div class="opt"><span class="caps">Pack</span><div class="seg" role="group" aria-label="Pack" data-pack>${packBtns}</div></div>
      <div class="opt row"><span class="caps">Quantity</span><div class="qty" role="group" aria-label="Quantity"><button type="button" data-dec aria-label="One fewer">&minus;</button><output data-qty>1</output><button type="button" data-inc aria-label="One more">+</button></div></div>
      <div class="priceline"><span class="mrp caps">MRP</span><span class="price" data-total>${inr(d.price)}</span><span class="small" data-unit>${inr(d.price)} each</span></div>
      <p class="small incl">Inclusive of all taxes</p>
      <div class="buyrow" data-buyrow><button type="button" class="btn primary" data-add>Add to cart</button><button type="button" class="btn ghost" data-now>Order now</button></div>
      <p class="small assure">${esc(cat.shipping.note)} Nothing is charged online.</p>
      <ul class="points">${p.points.map(x => '<li>' + esc(x) + '</li>').join('')}</ul>
      <div class="acc">
        <details open><summary>Specification</summary><div class="acc-in">
          <table class="stable"><thead><tr><th>Format</th><th>Volume</th><th>Pack</th><th>MRP</th></tr></thead><tbody>${rows}</tbody></table>
          <dl class="facts">${facts}</dl>
          <p class="small">pH and TDS are target specifications. Every batch is measured before it is released.</p>
        </div></details>
        <details><summary>The water</summary><div class="acc-in"><p>${esc(p.story)}</p><p>At the plant it passes through sand and activated carbon, micron filters and a reverse-osmosis membrane, has its minerals balanced to this water&rsquo;s profile, and is disinfected with ozone and ultraviolet light before it is filled in a clean room. The batch report is available on request.</p><p><a class="link" href="/source">Read the Source</a> &middot; <a class="link" href="/craft">See the line</a></p></div></details>
        <details><summary>Serving</summary><div class="acc-in"><p>${esc(p.serve)}</p></div></details>
        <details><summary>Delivery and care</summary><div class="acc-in"><p>${esc(cat.shipping.note)} If anything arrives damaged, write to <a class="link" href="mailto:hello@onyxaura.in">hello@onyxaura.in</a> with your order number and a photograph, and we will put it right.</p></div></details>
      </div>
      <p class="small venue">Ordering for a venue, a cabin or an event? <a class="link" href="/contact?seg=corporate">Write to us.</a></p>
    </div>`;
  }
  const tdsSec = p.tds ? `
    <div class="tds" data-tdsscale data-id="${p.id}">
      <p class="caps gold" style="margin:70px 0 22px">Mineral content (TDS)</p>
      <h3 class="tds-h serif">Soft, by design.</h3>
      <p class="small tds-sub">Total dissolved solids, in parts per million. Tasting panels rate water under 300 ppm as excellent.</p>
      <div class="tds-track" data-ttrack><span class="tds-band ex"><i>Excellent</i></span><span class="tds-band gd"><i>Good</i></span></div>
      <p class="tds-read small" data-tread aria-live="polite"></p>
    </div>` : '';
  return pageHead + `<body data-page="collection" class="shop-page pdp-page${soon ? ' pdp-soon' : ''}">
<!--HEADER--><!--/HEADER-->
<main data-pdp>
<div class="wrap pdp-wrap">
  <nav class="crumbs small" aria-label="Breadcrumb"><a href="/collection">Collection</a><span aria-hidden="true">/</span><span aria-current="page">${esc(p.name)}</span></nav>
  <div class="pdp-grid">
    ${gallery}
    ${panel}
  </div>
</div>
${origin}
<section class="ph-sec">
  <div class="wrap">
    <p class="caps gold" style="margin-bottom:22px">Target pH</p>
    <h2>Where it sits.</h2>
    <p class="lead" style="margin-top:22px">${esc(p.name)} is specified at pH ${range(p.ph)}. Move along the scale to see where the other waters sit.</p>
    <div class="ph" data-ph data-id="${p.id}">
      <div class="ph-track" data-track><input class="ph-input" type="range" min="0" max="14" step="0.1" value="${((p.ph[0] + p.ph[1]) / 2).toFixed(1)}" aria-label="Explore the pH scale"></div>
      <p class="ph-read" data-read aria-live="polite"></p>
      <div class="ph-chips" role="group" aria-label="Show other pieces" data-chips></div>
    </div>${tdsSec}
    <p class="small" style="margin-top:34px">Target specifications. Each batch is measured and recorded before release.</p>
  </div>
</section>
<section class="more-sec">
  <div class="wrap">
    <p class="caps gold" style="margin-bottom:22px">Collection</p>
    <h2>The rest of the house.</h2>
    <div class="mini-grid">${more}</div>
    ${goldStrip}
  </div>
</section>
${soon ? '' : `<div class="stickybuy" data-sticky hidden><div class="sb-in"><span class="sb-name serif">${esc(p.name)}</span><span class="price" data-total2>${inr(d.price)}</span><button type="button" class="btn primary" data-add2>Add to cart</button></div></div>`}
<script type="application/json" id="pdp-data">${JSON.stringify(data)}</script>
</main>
<!--FOOTER--><!--/FOOTER-->
<script src="/assets/site.js"></script>
<script src="/assets/wire.js" defer></script>
<script src="/assets/shop.js" defer></script>
</body>
</html>
`;
}

fs.writeFileSync(path.join(root, 'collection.html'), collectionPage());
fs.mkdirSync(path.join(root, 'collection'), { recursive: true });
